// main.ts
import { NestFactory } from "@nestjs/core"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"
import { AppModule } from "./app.module"

async function bootstrap() {
    const app = await NestFactory.create(AppModule)

    const config = new DocumentBuilder()
        .setTitle("Do'kon API")
        .setDescription("Buyurtmalar va mahsulotlar")
        .setVersion("1.0")
        .addBearerAuth()
        .build()

    const documentFactory = () => SwaggerModule.createDocument(app, config)
    SwaggerModule.setup("docs", app, documentFactory)   // http://localhost:3000/docs

    await app.listen(3000)
}
bootstrap()

SwaggerModule.setup("docs", app, documentFactory, {
    useGlobalPrefix: true,                  // setGlobalPrefix("api") bo'lsa: /api/docs
    jsonDocumentUrl: "openapi.json",        // /openapi.json
    yamlDocumentUrl: "openapi.yaml",
    customSiteTitle: "Do'kon API hujjatlari",
    customCss: ".swagger-ui .topbar { display: none }",
    swaggerOptions: {
        persistAuthorization: true,         // token sahifa yangilanganda ham saqlanadi
        docExpansion: "none",               // bo'limlar yig'ilgan holda ochiladi
        tagsSorter: "alpha",
        operationsSorter: "alpha",
    },
})

// generate-metadata.ts — bir marta yoki watch rejimida ishga tushiriladi
import { PluginMetadataGenerator } from "@nestjs/cli/lib/compiler/plugins/plugin-metadata-generator"
import { ReadonlyVisitor } from "@nestjs/swagger/plugin"
import { join } from "node:path"

new PluginMetadataGenerator().generate({
    visitors: [new ReadonlyVisitor({ introspectComments: true, pathToSource: join(process.cwd(), "src") })],
    outputDir: join(process.cwd(), "src"),
    watch: true,
    tsconfigPath: "tsconfig.build.json",
})

// main.ts
