import { Body, Controller, Get, Module, Param, Post } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"

@Controller("books")
class BooksController {
    @Get() list() { return [] }
    @Get(":id") one(@Param("id") id: string) { return { id } }
    @Post() create(@Body() body: object) { return body }
}
@Module({ controllers: [BooksController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().setTitle("Kutubxona").build())
    for (const [path, ops] of Object.entries(doc.paths)) {
        console.log(path, "→", Object.keys(ops).map(m => m.toUpperCase()).join(", "))
    }
    console.log("parametr:", JSON.stringify(doc.paths["/books/{id}"].get!.parameters))
    await app.close()
}
main()

