import { Controller, Get, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"

@Controller("users") class UsersController { @Get() list() { return [] } }
@Module({ controllers: [UsersController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })   // listen() shart emas
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().setTitle("Shop API").setVersion("2.1.0").build())
    const file = join(mkdtempSync(join(tmpdir(), "openapi-")), "openapi.json")
    writeFileSync(file, JSON.stringify(doc, null, 2))
    const saved = JSON.parse(readFileSync(file, "utf8"))
    console.log("saqlandi: openapi.json | versiya:", saved.info.version, "| openapi:", saved.openapi)
    await app.close()
}
main()

