import { Controller, Get, INestApplication, Module } from "@nestjs/common"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"

@Controller("x") class X { @Get() get() { return 1 } }
@Module({ controllers: [X] }) class AppModule {}

function setupSwagger(app: INestApplication, env: string) {
    if (env === "production") return
    SwaggerModule.setup("docs", app, SwaggerModule.createDocument(app, new DocumentBuilder().build()))
}

async function main() {
    for (const env of ["development", "production"]) {
        const http = await testApp(AppModule, app => setupSwagger(app, env))
        console.log(`${env}: GET /docs →`, (await fetch((await http.app.getUrl()) + "/docs")).status)
        await http.close()
    }
}
main()

import { Controller, Get, Module } from "@nestjs/common"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"
import type { NextFunction, Request, Response } from "express"

@Controller("x") class X { @Get() get() { return 1 } }
@Module({ controllers: [X] }) class AppModule {}

const docsAuth = (req: Request, res: Response, next: NextFunction) => {
    const expected = "Basic " + Buffer.from("dev:docs123").toString("base64")
    if (req.headers.authorization !== expected) { res.setHeader("WWW-Authenticate", "Basic"); res.status(401).end(); return }
    next()
}

async function main() {
    const http = await testApp(AppModule, app => {
        app.use(["/docs", "/docs-json"], docsAuth)
        SwaggerModule.setup("docs", app, SwaggerModule.createDocument(app, new DocumentBuilder().build()))
    })
    const url = (await http.app.getUrl()) + "/docs-json"
    console.log("parolsiz:", (await fetch(url)).status)
    console.log("parol bilan:", (await fetch(url, { headers: { Authorization: "Basic " + Buffer.from("dev:docs123").toString("base64") } })).status)
    await http.close()
}
main()

