}
@Module({ controllers: [OrdersController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().build())
    const missing: string[] = []
    for (const [path, ops] of Object.entries(doc.paths))
        for (const [method, op] of Object.entries(ops as Record<string, any>)) if (!op.summary) missing.push(`${method.toUpperCase()} ${path}`)
    console.log(missing.length ? `❌ summary yo'q: ${missing.join(", ")}` : "✔ hammasi hujjatlangan")
    await app.close()
}
