type Doc = { paths: Record<string, object>; components: { schemas: Record<string, object> } }
const users: Doc = { paths: { "/users": {}, "/users/{id}": {} }, components: { schemas: { User: {} } } }
const orders: Doc = { paths: { "/orders": {} }, components: { schemas: { Order: {}, User: {} } } }
function merge(...docs: [string, Doc][]) {
    const out: Doc = { paths: {}, components: { schemas: {} } }
    for (const [prefix, d] of docs) {
        for (const [p, v] of Object.entries(d.paths)) out.paths[`/${prefix}${p}`] = v
        for (const [n, s] of Object.entries(d.components.schemas)) out.components.schemas[n in out.components.schemas ? `${prefix}_${n}` : n] = s
    }
    return out
}
const gw = merge(["users-svc", users], ["orders-svc", orders])
console.log(Object.keys(gw.paths))
console.log(Object.keys(gw.components.schemas))

