import { Body, Controller, Module, Post } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"

// Haqiqiy kutubxona o'rniga "mini" Standard Schema: faqat ~standard xossasi bor
const loginSchema = {
    kind: "login",
    "~standard": { version: 1, vendor: "mini", validate: (value: unknown) => ({ value }) },
}

@Controller("auth")
class AuthController {
    @Post("login") login(@Body({ schema: loginSchema as any }) body: object) { return body }
}
@Module({ controllers: [AuthController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().build(), {
        standardSchemaConverter: (schema: any) =>
            schema.kind === "login"
                ? { schema: { type: "object", properties: { phone: { type: "string" } }, required: ["phone"] } }
                : undefined,
    })
    console.log(JSON.stringify(doc.paths["/auth/login"].post!.requestBody))
    await app.close()
}
main()

