class CardPayment { @ApiProperty({ enum: ["card"] }) type: "card"; @ApiProperty() last4: string }
class CashPayment { @ApiProperty({ enum: ["cash"] }) type: "cash"; @ApiProperty() change: number }

@Controller("payments")
@ApiExtraModels(CardPayment, CashPayment)
class PaymentsController {
    @Get(":id")
    @ApiOkResponse({ schema: { oneOf: [{ $ref: getSchemaPath(CardPayment) }, { $ref: getSchemaPath(CashPayment) }], discriminator: { propertyName: "type" } } })
    one() { return { type: "card", last4: "1234" } }
}
@Module({ controllers: [PaymentsController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().build())
    console.log(JSON.stringify((doc.paths["/payments/{id}"].get!.responses["200"] as any).content["application/json"].schema))
    await app.close()
}
main()

