import { Body, Controller, Get, Module, Post } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ApiBody, ApiOkResponse, ApiProperty, DocumentBuilder, SwaggerModule } from "@nestjs/swagger"

class BaseDto {
    @ApiProperty() id!: number
    @ApiProperty() createdAt!: Date
}
class ProductDto extends BaseDto { @ApiProperty() name!: string }
class TagDto { @ApiProperty() label!: string }

@Controller()
class ShopController {
    @Post("tags") @ApiBody({ type: [TagDto] }) addTags(@Body() tags: TagDto[]) { return tags }
    @Get("products") @ApiOkResponse({ type: ProductDto, isArray: true }) products() { return [] }
}
@Module({ controllers: [ShopController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().build())
    const schema = (o: any) => JSON.stringify(o.content["application/json"].schema)
    console.log("tana:", schema(doc.paths["/tags"].post!.requestBody))
    console.log("javob:", schema((doc.paths["/products"].get!.responses as any)["200"]))
    console.log("ProductDto maydonlari:", Object.keys((doc.components!.schemas!.ProductDto as any).properties))
    await app.close()
}
main()

import { Controller, Get, Module } from "@nestjs/common"
