}
main()

import { Controller, Get, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ApiOAuth2, DocumentBuilder, SwaggerModule } from "@nestjs/swagger"

@Controller("account")
class AccountController {
    @Get("profile") @ApiOAuth2(["profile"], "oauth2") profile() { return {} }
    @Get("orders") @ApiOAuth2(["profile", "orders:read"], "oauth2") orders() { return [] }
    @Get("ping") ping() { return "pong" }
}
@Module({ controllers: [AccountController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const config = new DocumentBuilder().addOAuth2({
        type: "oauth2",
        flows: { implicit: { authorizationUrl: "https://auth.recipe.uz/authorize", scopes: { profile: "Profil", "orders:read": "Buyurtmalarni o'qish" } } },
    }, "oauth2").build()
    const doc = SwaggerModule.createDocument(app, config)
    for (const [path, item] of Object.entries(doc.paths)) console.log(path.padEnd(18), JSON.stringify(item.get!.security ?? []))
    await app.close()
}
main()

