import { Body, Controller, Module, Post } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { ApiCallbacks, ApiProperty, ApiWebhook, DocumentBuilder, SwaggerModule } from "@nestjs/swagger"

class PaidEvent {
    @ApiProperty() orderId!: number
    @ApiProperty() amount!: number
}

@Controller()
class HooksController {
    @Post("subscribe")
    @ApiCallbacks({
        name: "onOrderPaid",
        callbackUrl: "{$request.body#/callbackUrl}",
        method: "post",
        requestBody: { type: PaidEvent },
        expectedResponse: { status: 200, description: "Qabul qilindi" },
    })
    subscribe(@Body() body: { callbackUrl: string }) { return body }

    @Post("hooks/order-paid") @ApiWebhook("orderPaid")
    paid(@Body() event: PaidEvent) { return event }
}
@Module({ controllers: [HooksController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc: any = SwaggerModule.createDocument(app, new DocumentBuilder().setOpenAPIVersion("3.1.0").build())
    console.log("paths:", Object.keys(doc.paths))
    console.log("webhooks:", Object.keys(doc.webhooks))
    console.log("callbacks:", Object.keys(doc.paths["/subscribe"].post.callbacks.onOrderPaid))
    await app.close()
}
main()

import { Body, Controller, Module, Post } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import { DocumentBuilder, SwaggerModule } from "@nestjs/swagger"
import { z } from "zod"

const CreateUserSchema = z.object({
    name: z.string().min(2),
    age: z.number().int().min(0).max(120).optional(),
})

@Controller("users")
class UsersController {
    @Post() create(@Body({ schema: CreateUserSchema }) body: z.infer<typeof CreateUserSchema>) { return body }
}
@Module({ controllers: [UsersController] }) class AppModule {}

async function main() {
    const app = await NestFactory.create(AppModule, { logger: false })
    const doc = SwaggerModule.createDocument(app, new DocumentBuilder().build())
    console.log(JSON.stringify(doc.paths["/users"].post!.requestBody, null, 1))
    await app.close()
}
main()
